9	#[ORM\Embeddable]
10	final readonly class Money
11	{
12	    public function __construct(
13	        #[ORM\Column]
14	        public int $amountInCents,
15	        #[ORM\Column(enumType: Currency::class)]
16	        public Currency $currency,
17	    ) {
18	        if ($amountInCents < 0) {
19	            throw new \InvalidArgumentException('Money cannot be negative');
20	        }
21	    }
22	
23	    public static function zero(Currency $currency): self
24	    {
25	        return new self(0, $currency);
26	    }
27	
28	    public function add(self $other): self
29	    {
30	        if ($this->currency !== $other->currency) {
31	            // Vědomá zkratka jako v knize: pojmenovaná výjimka by v Shared Kernelu
32	            // znamenala další sdílený typ.
33	            throw new \DomainException(
34	                "Cannot add {$this->currency->value} and {$other->currency->value}"
35	            );
36	        }
37	
38	        return new self($this->amountInCents + $other->amountInCents, $this->currency);
39	    }
40	
41	    public function subtract(self $other): self
42	    {
43	        if ($this->currency !== $other->currency) {
44	            throw new \DomainException(
45	                "Cannot subtract {$other->currency->value} from {$this->currency->value}"
46	            );
47	        }
48	
49	        return new self($this->amountInCents - $other->amountInCents, $this->currency);
50	    }
51	
52	    public function multiply(int $factor): self
53	    {
54	        return new self($this->amountInCents * $factor, $this->currency);
55	    }
56	
57	    public function equals(self $other): bool
58	    {
59	        return $this->amountInCents === $other->amountInCents
60	            && $this->currency === $other->currency;
61	    }
